package ru.fifth.horror.entity;
import net.minecraft.entity.Entity;import net.minecraft.entity.EntityType;import net.minecraft.nbt.NbtCompound;import net.minecraft.util.math.BlockPos;import net.minecraft.world.World;import java.util.UUID;
public final class LiftPanelEntity extends Entity{private UUID liftUuid;private int enabledMask=(0x1FF&~(1<<(2-1))&~(1<<(5-1))&~(1<<(8-1)));public LiftPanelEntity(EntityType<? extends LiftPanelEntity> t,World w){super(t,w);setNoGravity(true);}public UUID getLiftUuid(){return liftUuid;}public void setLiftUuid(UUID u){liftUuid=u;}public boolean enabled(int f){return (enabledMask&(1<<(f-1)))!=0;}public void setEnabled(int f,boolean e){int bit=1<<(f-1);enabledMask=e?(enabledMask|bit):(enabledMask&~bit);}public int getEnabledMask(){return enabledMask;}@Override protected void initDataTracker(){}@Override protected void readCustomDataFromNbt(NbtCompound n){liftUuid=n.containsUuid("FivenLiftUuid")?n.getUuid("FivenLiftUuid"):null;enabledMask=n.contains("FivenEnabledMask")?n.getInt("FivenEnabledMask"):enabledMask;}@Override protected void writeCustomDataToNbt(NbtCompound n){if(liftUuid!=null)n.putUuid("FivenLiftUuid",liftUuid);n.putInt("FivenEnabledMask",enabledMask);}@Override public void tick(){super.tick();setVelocity(0,0,0);}}
